 "content": "from collections import defaultdict


def transform(grid):
    h, w = len(grid), len(grid[0])
    positions = defaultdict(list)
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v:
                positions[v].append((r, c))

    frames = []
    for color, cells in positions.items():
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        # Objects are rectangular frames; their outer border is complete.
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        if (all(grid[r0][c] == color for c in range(c0, c1 + 1)) and
            all(grid[r1][c] == color for c in range(c0, c1 + 1)) and
            all(grid[r][c0] == color for r in range(r0, r1 + 1)) and
            all(grid[r][c1] == color for r in range(r0, r1 + 1))):
            frames.append((color, r0, r1, c0, c1))

    patterned = []
    for frame in frames:
        color, r0, r1, c0, c1 = frame
        pattern = [[grid[r][c] != 0 for c in range(c0 + 1, c1)]
                   for r in range(r0 + 1, r1)]
        if any(any(row) for row in pattern):
            patterned.append((frame, pattern))
    if not patterned:
        return [row[:] for row in grid]

    source, pattern = patterned[0]
    _, sr0, sr1, sc0, sc1 = source
    sh, sw = sr1 - sr0 + 1, sc1 - sc0 + 1
    keep = [f for f in frames if f[2] - f[1] + 1 == sh and f[4] - f[3] + 1 == sw]
    out = [row[:] for row in grid]
    # Clear all detected frame objects, including unmatched sizes.
    for color, r0, r1, c0, c1 in frames:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if grid[r][c] == color:
                    out[r][c] = 0
    # Recreate the matching frames and transfer the source's interior motif.
    for color, r0, r1, c0, c1 in keep:
        for c in range(c0, c1 + 1):
            out[r0][c] = out[r1][c] = color
        for r in range(r0, r1 + 1):
            out[r][c0] = out[r][c1] = color
        for dr in range(len(pattern)):
            for dc in range(len(pattern[dr])):
                out[r0 + 1 + dr][c0 + 1 + dc] = color if pattern[dr][dc] else 0
    return out
